#include <stdint.h>
void crc64_ecma_step_model(const uint32_t in[3], uint32_t out[3]) {
    uint64_t crc = ((uint64_t)in[1] << 32) | in[0];
    uint32_t data = in[2];
    for (int i = 0; i < 4; i++) {
        uint64_t byte = (data >> (i * 8)) & 0xFF;
        crc = crc ^ (byte << 56);
        for (int b = 0; b < 8; b++) {
            uint64_t mask = (uint64_t)0 - ((crc >> 63) & 1);
            crc = (crc << 1) ^ (0x42F0E1EBA9EA3693ull & mask);
        }
    }
    out[0] = (uint32_t)crc;
    out[1] = (uint32_t)(crc >> 32);
    out[2] = 0;
}

#include <stdint.h>
void crc32_step_model(const uint32_t in[3], uint32_t out[3]) {
    uint32_t crc = in[0];
    for (int w = 0; w < 2; w++) {
        uint32_t data = in[w + 1];
        for (int i = 0; i < 4; i++) {
            uint32_t byte = (data >> (i * 8)) & 0xFF;
            crc = crc ^ byte;
            for (int b = 0; b < 8; b++) {
                uint32_t mask = (uint32_t)0 - (crc & 1);
                crc = (crc >> 1) ^ (0xEDB88320 & mask);
            }
        }
    }
    out[0] = crc;
    out[1] = 0;
    out[2] = 0;
}

#include <stdint.h>
void crc16_step_model(const uint32_t in[3], uint32_t out[3]) {
    uint32_t crc = in[0] & 0xFFFF;
    for (int w = 0; w < 2; w++) {
        uint32_t data = in[w + 1];
        for (int i = 0; i < 4; i++) {
            uint32_t byte = (data >> (i * 8)) & 0xFF;
            crc = crc ^ byte;
            for (int b = 0; b < 8; b++) {
                uint32_t mask = (uint32_t)0 - (crc & 1);
                crc = (crc >> 1) ^ (0xA001 & mask);
            }
